/** Regenerates src/elcinema/images.ts from the uploaded asset pointers. */
import { readdir, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";

const dir = "src/assets/img";
const files = (await readdir(dir)).filter((f) => f.endsWith(".asset.json"));
const entries: string[] = [];
for (const f of files) {
  const ptr = JSON.parse(await readFile(join(dir, f), "utf8"));
  const name = ptr.original_filename;
  entries.push(`  ${JSON.stringify(name)}: ${JSON.stringify(ptr.url)},`);
}
const body = `/**
 * Local image manifest, generated by scripts/build-images.ts from the asset
 * pointers in src/assets/img. Keys are image filenames used by the dataset
 * JSON files; values are the stable local asset URLs.
 */
export const IMAGES: Record<string, string> = {
${entries.join("\n")}
};

/** Resolve a dataset image key to its local URL (empty string when absent). */
export function img(key: string | null | undefined): string {
  return (key && IMAGES[key]) || "";
}
`;
await writeFile("src/elcinema/images.ts", body);
console.log(`wrote src/elcinema/images.ts with ${entries.length} entries`);
